from abc import ABC, abstractproperty
from taf.gnb.oam.ne3s.ws.filter import MessageFilter


class NE3SInterface(ABC):
    @abstractproperty
    def connection(self):
        raise NotImplementedError()

    def disconnect(self):
        self.connection.teardown_connection()

    def create_filter(self, filter_name, *streams):
        return MessageFilter(name=filter_name, streams=streams)
